import json,subprocess,itertools
s=[0]
for k in range(1,73):s.append((100003-200003*k+300007*k**3 if k<=55 else s[k-24]+s[k-55])%1000000)
boxes=[]
for i in range(12):
 a=s[6*i+1:6*i+7];lo=[x%10000 for x in a[:3]];hi=[lo[j]+1+a[j+3]%399 for j in range(3)];boxes.append((lo,hi))
def volume(n):
 total=0
 for mask in range(1,1<<n):
  selected=[boxes[i] for i in range(n) if mask>>i&1];v=1
  for j in range(3):v*=max(0,min(b[1][j] for b in selected)-max(b[0][j] for b in selected))
  total+=v*(1 if bin(mask).count("1")%2 else -1)
 return total
